module logic;
use model {Summary,Job};
use util {reverse};
record Scan {pending:List<Job>,completed:List<I64>,budget:I64,found:Bool,id:I64,cost:I64}
record Remove {pending:List<Job>,output:List<Job>,id:I64}
record State {pending:List<Job>,completed:List<I64>,budget:I64,spent:I64,order:List<I64>,active:Bool}
record Check {pending:List<I64>,found:Bool}

fn has(items:List<I64>,value:I64)->Bool {
 let final=fold(i in List::length(items), state:Check=Check {pending:items,found:false}) {
  Check {pending:List::tail(state.pending),found:state.found || List::head(state.pending)==value}
 };
 final.found
}

fn deps_done(deps:List<I64>,completed:List<I64>)->Bool {
 let final=fold(i in List::length(deps), state:Check=Check {pending:deps,found:true}) {
  Check {pending:List::tail(state.pending),found:state.found && has(completed,List::head(state.pending))}
 };
 final.found
}

fn scan(jobs:List<Job>,completed:List<I64>,budget:I64)->Scan {
 let final=fold(i in List::length(jobs), state:Scan=Scan {pending:jobs,completed:completed,budget:budget,found:false,id:0,cost:0}) {
  let job=List::head(state.pending);
  let eligible=deps_done(job.deps,state.completed) && job.cost<=state.budget;
  let better=eligible && ((!state.found) || job.id<state.id);
  Scan {pending:List::tail(state.pending),completed:state.completed,budget:state.budget,found:state.found || eligible,id:if (better) {job.id} else {state.id},cost:if (better) {job.cost} else {state.cost}}
 };
 final
}

fn remove(jobs:List<Job>,id:I64)->List<Job> {
 let final=fold(i in List::length(jobs), state:Remove=Remove {pending:jobs,output:List::empty<Job>(),id:id}) {
  let job=List::head(state.pending);
  Remove {pending:List::tail(state.pending),output:if (job.id==state.id) {state.output} else {List::prepend(job,state.output)},id:state.id}
 };
 final.output
}

fn run(jobs:List<Job>,budget:I64)->Summary {
 let final=while(state:State=State {pending:jobs,completed:List::empty<I64>(),budget:budget,spent:0,order:List::empty<I64>(),active:true}; state.active) {
  let choice=scan(state.pending,state.completed,state.budget);
  State {pending:if (choice.found) {remove(state.pending,choice.id)} else {state.pending},completed:if (choice.found) {List::prepend(choice.id,state.completed)} else {state.completed},budget:if (choice.found) {state.budget-choice.cost} else {state.budget},spent:if (choice.found) {state.spent+choice.cost} else {state.spent},order:if (choice.found) {List::prepend(choice.id,state.order)} else {state.order},active:choice.found}
 };
 Summary {order:reverse(final.order),spent:final.spent,blocked:List::length(final.pending)}
}

